import sys
input = sys.stdin.readline

def solve():
	n = int(input())
	g = [list(input().rstrip()) for __ in range(2)]
	(left, right) = (-1, 0)
	for i in range(n):
		if g[0][i] == '*' or g[1][i] == '*':
			if left == -1:
				left = i
			right = i
	ret = 0
	f = [0] * (n + 1)
	mid = (left + right) // 2
	for i in range(right):
		if f[i]:
			if g[0][i + 1] == '.' and g[1][i + 1] == '.':
				f[i + 1] = 1
			ret += 1
			continue
		if g[0][i] == '*' and g[1][i] == '*' and (g[0][i + 1] == '.') and (g[1][i + 1] == '.'):
			f[i + 1] = 1
			ret += 2
			continue
		if g[0][i] == '*':
			if g[0][i + 1] == '.' and g[1][i] == '.':
				g[0][i + 1] = '*'
			ret += 1
		if g[1][i] == '*':
			if g[1][i + 1] == '.' and g[0][i] == '.':
				g[1][i + 1] = '*'
			ret += 1
	cnt = 0
	if g[0][right] == '*':
		cnt += 1
	if g[1][right] == '*':
		cnt += 1
	return ret + (1 if cnt == 2 else 0)
for __ in range(int(input())):
	print(solve())
